const D = { energy: .62, scale: 1, speed: 1, density: .55, band: .6, hue: 210, x: .5, y: .5, style: 'sky', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// A metaphase chromosome spread, the classic cytogenetics image. Condensed
// chromosomes lie scattered across the slide, each a pair of sister chromatids
// pinched at a centromere into the familiar X, striped along its arms with a
// G-banding pattern. On the wet slide they never sit still: each jiggles with
// Brownian rotation and the whole spread drifts slowly, and every few seconds a
// fresh metaphase is captured -- all the chromosomes ease to a new scatter and
// settle, a perpetual re-drop that never converges. Offered as spectral
// karyotyping (every chromosome a vivid colour), bright-field Giemsa banding,
// DAPI fluorescence, or sorted into a ranked karyotype chart.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sp = 0.25 + P.speed * 0.9;

const sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7 + 7.7) * 43758.5453; return s - Math.floor(s); };
const h2 = (k, n, c) => { const s = Math.sin(k * 12.9898 + n * 78.233 + c * 37.719 + sd * 3.11) * 43758.5453; return s - Math.floor(s); };

const nChr = Math.round(16 + P.density * 40);
if (!S.chr || S.seedUsed !== P.seed || S.nU !== nChr) {
  S.seedUsed = P.seed; S.nU = nChr;
  S.chr = [];
  for (let k = 0; k < nChr; k++) {
    const size = 0.4 + fr(k * 7 + 3) * 0.6;            // relative chromosome length (rank)
    const nb = 4 + Math.floor(fr(k * 11 + 4) * 7);
    const bands = [];
    for (let b = 0; b < nb; b++) bands.push({ p: (b + 0.5) / nb, dark: fr(k * 13 + b * 3 + 20) });
    S.chr.push({
      size, cp: 0.32 + fr(k * 17 + 5) * 0.24,           // centromere position
      nb, bands, hueC: (k / nChr * 300 + fr(k * 19 + 6) * 24) % 360,
      jr: 0.02 + fr(k * 23 + 7) * 0.04, jph: fr(k * 29 + 8) * 6.283,
      rrate: 0.05 + fr(k * 31 + 9) * 0.1
    });
    S.chr[k].rank = 0;
  }
  // rank by size (descending) for karyotype layout
  const order = S.chr.map((c, i) => i).sort((a, b) => S.chr[b].size - S.chr[a].size);
  for (let i = 0; i < order.length; i++) S.chr[order[i]].rank = i;
}

const t = K.t;
const style = P.style;
const glow = 0.4 + P.energy * 1.3 + A.rms * 0.35;
const bandC = 0.3 + P.band * 0.7;

// re-drop cycle: chromosomes ease from scatter(n) to scatter(n+1) then settle
const dropPeriod = 7.5 / sp;
const dc = t / dropPeriod, dropN = Math.floor(dc), dph = dc - dropN;
const ease = (x) => { const e = Math.min(1, x * 1.7); return e * e * e * (e * (e * 6 - 15) + 10); };
const eph = ease(dph);
// slow whole-spread drift + rotation (slide moving under scope)
const driftX = Math.sin(t * 0.06 * sp) * u * 0.03 + Math.sin(t * 0.019 * sp + 1.2) * u * 0.02;
const driftY = Math.cos(t * 0.05 * sp) * u * 0.03 + Math.sin(t * 0.014 * sp + 0.5) * u * 0.02;
const fieldRot = 0.08 * Math.sin(t * 0.03 * sp) + 0.04 * Math.sin(t * 0.011 * sp);

let bgH, bgS, bgB, mode;
if (style === 'giemsa') { bgH = 275; bgS = 12; bgB = 74; mode = 'giemsa'; }
else if (style === 'dapi') { bgH = 232; bgS = 60; bgB = 8; mode = 'dapi'; }
else if (style === 'karyotype') { bgH = 210; bgS = 8; bgB = 82; mode = 'karyotype'; }
else { bgH = 240; bgS = 45; bgB = 7; mode = 'sky'; }
const pale = (mode === 'giemsa' || mode === 'karyotype');

push();
noStroke(); rectMode(CENTER);
fill(bgH, bgS, bgB); rect(width / 2, height / 2, width * 1.02, height * 1.02);
if (pale) { // faint slide texture / condenser
  for (let b = 0; b < 24; b++) { fill(bgH, bgS * 1.4, bgB - 4 - fr(b) * 6, 12); ellipse(fr(b * 3 + 500) * width, fr(b * 5 + 501) * height, u * (0.15 + fr(b * 7) * 0.25), u * (0.15 + fr(b * 6) * 0.25)); }
} else { // dark modes: condenser pool + diffuse cytoplasm/counterstain wash to seat the spread
  for (let ri = 5; ri >= 1; ri--) { fill(bgH, bgS * 0.6, Math.min(46, bgB + (6 - ri) * 4), 18); ellipse(width * 0.5, height * 0.5, u * (0.4 + ri * 0.16) * 2, u * (0.4 + ri * 0.16) * 1.9); }
  for (let b = 0; b < 34; b++) { fill((bgH + 6) % 360, bgS * 0.7, bgB + 5 + fr(b * 2) * 7, 8); ellipse(fr(b * 3 + 600) * width, fr(b * 5 + 601) * height, u * (0.1 + fr(b * 7) * 0.14) * 2, u * (0.1 + fr(b * 6) * 0.14) * 2); }
}

const cxc = width * 0.5 + driftX + (P.x - 0.5) * width * 0.2, cyc = height * 0.5 + driftY + (P.y - 0.5) * height * 0.2;
push(); translate(cxc, cyc); rotate(fieldRot);

if (mode === 'sky' || mode === 'dapi') blendMode(ADD);

// karyotype grid dims
const kcols = Math.ceil(Math.sqrt(nChr * width / height));
const krows = Math.ceil(nChr / kcols);

for (let k = 0; k < S.chr.length; k++) {
  const c = S.chr[k];
  let nx, ny, rot;
  if (mode === 'karyotype') {
    const col = c.rank % kcols, row = (c.rank / kcols | 0);
    nx = (col + 0.5) / kcols - 0.5; ny = (row + 0.5) / krows - 0.5;
    nx *= 0.86; ny *= 0.82;
    rot = Math.sin(t * c.rrate * sp + c.jph) * 0.08;                 // gentle upright jiggle
  } else {
    const ax = (h2(k, dropN, 1) - 0.5) * 0.72, ay = (h2(k, dropN, 2) - 0.5) * 0.68;
    const bx = (h2(k, dropN + 1, 1) - 0.5) * 0.72, by = (h2(k, dropN + 1, 2) - 0.5) * 0.68;
    nx = ax + (bx - ax) * eph; ny = ay + (by - ay) * eph;
    const ra = h2(k, dropN, 3) * 6.283, rb = h2(k, dropN + 1, 3) * 6.283;
    rot = ra + (rb - ra) * eph + Math.sin(t * c.rrate * sp + c.jph) * 0.25;  // + Brownian jiggle
    nx += Math.sin(t * 0.4 * sp + c.jph) * c.jr * 0.5; ny += Math.cos(t * 0.37 * sp + c.jph) * c.jr * 0.5;
  }
  const px = nx * Math.min(width, height * width / height) * 0.9, py = ny * height * 0.9;
  const Lc = c.size * u * 0.105 * P.scale, Wc = Lc * 0.3;
  if (Lc < 2) continue;

  push(); translate(px, py); rotate(rot);
  // colour
  let hue, satB;
  if (mode === 'sky') { hue = c.hueC; satB = 70; }
  else if (mode === 'dapi') { hue = 220; satB = 62; }
  else if (mode === 'giemsa') { hue = 285; satB = 26; }
  else { hue = (c.hueC * 0.3 + 210) % 360; satB = 22; }

  // chromosome body: two chromatids as one rounded rod, pinched at centromere
  const cpY = (c.cp - 0.5) * Lc;
  // draw arms as banded stack
  for (let b = 0; b < c.nb; b++) {
    const bd = c.bands[b];
    const yy = (bd.p - 0.5) * Lc;
    const bw = Wc * (Math.abs(yy - cpY) < Lc * 0.05 ? 0.6 : 1);   // constrict at centromere
    const bh = Lc / c.nb * 1.02;
    let br;
    if (pale) br = 30 + (1 - bd.dark) * 40 * bandC + (mode === 'karyotype' ? 8 : 0);   // dark bands on pale
    else br = Math.min(100, (40 + bd.dark * 55 * bandC) * glow);                        // bright bands on dark
    fill(hue, satB, br, pale ? 90 : (mode === 'dapi' || mode === 'sky' ? 82 : 88));
    rect(0, yy, bw, bh, bw * 0.4);
  }
  // outline / chromatid groove
  noFill(); strokeWeight(Math.max(0.4, Wc * 0.09));
  if (pale) stroke(hue, satB + 20, 22, 55); else stroke(hue, satB, Math.min(100, 80 * glow), 45);
  line(0, -Lc * 0.5 + Wc * 0.3, 0, Lc * 0.5 - Wc * 0.3);           // longitudinal split (two chromatids)
  noStroke();
  pop();
}
if (mode === 'sky' || mode === 'dapi') blendMode(BLEND);
pop();

pop();
if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(bgH, bgS, bgB, 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
